let current='evangelion', mode='deep';
let searchTimer=0, searchController=null;
let archive=JSON.parse(localStorage.getItem('constellationArchive')||'["evangelion","her"]');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function renderWork(){const w=works[current],p=$('#workPoster');p.className='poster '+(w.poster||'poster-live');p.style.backgroundImage=w.posterUrl?`linear-gradient(0deg,rgba(8,10,14,.35),rgba(8,10,14,.05)),url("${w.posterUrl}")`:'';p.innerHTML=w.posterUrl?`<span></span><i>${w.year||''}</i>`:`<span>${w.posterText||w.title}</span><i>${w.year||''}</i>`;$('#workType').textContent=w.type||w.mediaType;$('#workYear').textContent=w.year||'연도 미상';$('.award').textContent=w.award||w.source||'';$('#workTitle').textContent=w.title;$('#workCreator').textContent=w.creator;$('#workQuote').textContent=w.quote||`“${(w.description||'작품 설명이 아직 없습니다.').slice(0,180)}”`;$('#tasteTags').innerHTML=(w.tags?.length?w.tags:['Taste DNA 분석 전']).map(t=>`<span class="tag">#${t}</span>`).join('');const score=w.score||72;$('#bridgeScore').textContent=score;$('#bridgeMeter').style.width=score+'%';$('#saveBtn').classList.toggle('saved',archive.includes(current));$('#saveBtn').innerHTML=archive.includes(current)?'<span>✓</span> 내 성좌에 담김':'<span>＋</span> 내 성좌에 담기';renderRecs();}
function renderRecs(){if(!recs[current]){$('#connectionIntro').textContent='실제 작품 정보 연결 완료 · 추천 엔진은 다음 단계에서 활성화됩니다.';$('#recommendations').innerHTML=`<article class="rec-card integration-card"><span class="type">LIVE DATA</span><h4>${works[current].source}</h4><span class="creator">${works[current].externalId}</span><p class="reason">실제 외부 데이터가 공통 Work 형식으로 정규화되었습니다. Taste DNA 생성 후 교차 매체 추천 후보로 사용됩니다.</p></article>`;return}const list=recs[current]?.[mode]||recs[current]?.deep;const labels={story:'서사의 뼈대를 따라 연결했어요.',mood:'보고 난 뒤 남는 감정의 온도를 따라갑니다.',idea:'작품이 던지는 질문을 다음 매체로 이어갑니다.',visual:'색, 공간, 이미지의 리듬으로 연결했어요.',deep:'장르는 멀지만 취향의 핵심이 맞닿은 작품들입니다.'};$('#connectionIntro').textContent=labels[mode];$('#recommendations').innerHTML=list.map(r=>`<article class="rec-card"><span class="type">${r[0]}</span><span class="arrow">↗</span><h4>${r[1]}</h4><span class="creator">${r[2]}</span><p class="reason">“${r[3]}”</p></article>`).join('')}
function selectWork(id){current=id;mode='deep';$$('#modeTabs button').forEach(b=>b.classList.toggle('active',b.dataset.mode==='deep'));renderWork();$('#searchResults').hidden=true;$('#searchInput').value='';$('#workSection').scrollIntoView({behavior:'smooth',block:'start'})}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function save(){if(!recs[current]){toast('실제 작품 저장은 Supabase 단계에서 열립니다.');return}const i=archive.indexOf(current);if(i>=0){archive.splice(i,1);toast('내 성좌에서 꺼냈어요.')}else{archive.push(current);toast('새로운 별이 성좌에 추가됐어요.')}localStorage.setItem('constellationArchive',JSON.stringify(archive));$('#archiveCount').textContent=archive.length;renderWork()}
function showView(view){$('#discoverView').hidden=view!=='discover';$('#archiveView').hidden=view!=='archive';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='archive')renderArchive();scrollTo({top:0,behavior:'smooth'})}
function renderArchive(){const items=archive.length?archive:['evangelion'];const positions=[[25,57],[68,34],[72,76],[43,20],[30,85]];let lines='';for(let i=1;i<items.length;i++)lines+=`<line x1="${positions[0][0]}%" y1="${positions[0][1]}%" x2="${positions[i][0]}%" y2="${positions[i][1]}%" stroke="#555a64" stroke-width="1" stroke-dasharray="4 5"/>`;$('#constellation').innerHTML=`<svg>${lines}</svg>`+items.map((id,i)=>`<button class="star-node" style="left:${positions[i][0]}%;top:${positions[i][1]}%" data-node="${id}"><i></i>${works[id].title}</button>`).join('');$$('.star-node').forEach(n=>n.onclick=()=>{$('#connectionDetail').innerHTML=`<strong>${works[n.dataset.node].title}</strong> — ${works[n.dataset.node].tags.slice(0,3).join(' / ')}`});const dna=[['고독',91],['정체성',87],['기억',84],['인간 / 비인간',82],['멜랑콜리',78],['성장',64]];$('#dnaBars').innerHTML=dna.map(d=>`<div class="dna-row"><div class="dna-label"><span>${d[0]}</span><span>${d[1]}</span></div><div class="dna-track"><i style="width:${d[1]}%"></i></div></div>`).join('')}
$('#modeTabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;mode=b.dataset.mode;$$('#modeTabs button').forEach(x=>x.classList.toggle('active',x===b));renderRecs()};
$$('[data-work]').forEach(b=>b.onclick=()=>selectWork(b.dataset.work));$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#saveBtn').onclick=save;
$('#searchInput').oninput=e=>{const q=e.target.value.trim();clearTimeout(searchTimer);if(searchController)searchController.abort();if(q.length<2){$('#searchResults').hidden=true;return}$('#searchResults').hidden=false;$('#searchResults').innerHTML='<div class="search-message">영화·책·애니를 함께 찾고 있어요…</div>';$('#sourceStatus').className='source-status loading';searchTimer=setTimeout(async()=>{searchController=new AbortController();try{const r=await fetch(`/api/search?q=${encodeURIComponent(q)}`,{signal:searchController.signal});if(!r.ok)throw new Error('search');const data=await r.json();data.items.forEach(w=>works[w.id]=w);$('#searchResults').innerHTML=data.items.map(w=>`<button class="search-result" data-result="${w.id}"><span class="result-thumb" ${w.posterUrl?`style="background-image:url('${w.posterUrl}')"`:''}></span><span><strong>${w.title}<em class="provider-pill">${w.source}</em></strong><small>${w.mediaType} · ${w.year||'연도 미상'} · ${w.creator}</small></span></button>`).join('')||'<div class="search-message">검색 결과가 없습니다. 다른 제목으로 찾아보세요.</div>';const active=Object.entries(data.sources).filter(([,v])=>v==='ok').map(([k])=>k),waiting=Object.entries(data.sources).filter(([,v])=>v==='needs_key').map(([k])=>k);$('#sourceStatus').className='source-status '+(waiting.length?'partial':'');$('#sourceStatus').innerHTML=`<span class="live-dot"></span> ${active.join(' · ')} 실시간 연결${waiting.length?` · ${waiting.join(' · ')} 키 등록 대기`:''}`;}catch(err){if(err.name==='AbortError')return;$('#searchResults').innerHTML='<div class="search-message">검색 서비스에 잠시 연결할 수 없습니다. 다시 시도해 주세요.</div>';$('#sourceStatus').className='source-status partial';}},350)};
$('#searchResults').onclick=e=>{const b=e.target.closest('[data-result]');if(b)selectWork(b.dataset.result)};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#searchInput').focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#searchResults').hidden=true});
$('#archiveCount').textContent=archive.length;renderWork();
